contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function performing the test
    // params:
    //   caller - address that will attempt to call withdrawAll (simulated by using address(this) as caller via payable forwarding)
    //   seedDeposit - amount of wei to send to C so there is balance to withdraw
    // Note: we cannot change msg.sender directly; instead we rely on the fact that the contract deploying and calling this test
    // will have been set as owner in the original C. To allow generality, we require that address(this) is NOT the owner in the mutant's sense.
    function runTest(address payable maybeNotOwner, uint seedDeposit) public payable {
        // Preconditions: provide the seed deposit from this contract's balance
        require(address(this).balance >= seedDeposit, "insufficient balance for test deposit");

        // Fund C so there is balance to be withdrawn
        // send seedDeposit as plain transfer to trigger fallback and increment depositsCount
        (bool ok,) = address(c).call{value: seedDeposit}("");
        require(ok, "funding C failed");

        // Record balance of C before withdrawAll
        uint before = address(c).balance;

        // Call withdrawAll via c using this contract as msg.sender
        // This will succeed on original P only if this contract is the owner; on mutant M it will succeed only if this contract is NOT the owner.
        // We perform the call and capture whether it reverted.
        bool success;
        // perform low-level call to detect revert without bubbling
        (success,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        uint after = address(c).balance;

        // General rule: if withdrawAll succeeded then C's balance must have decreased by at least the amount available before the call
        // For original contract P, when owner calls withdrawAll it will transfer the entire balance, so success implies after < before.
        // For mutant M, withdrawAll will succeed when caller is NOT owner, which would incorrectly allow non-owner calls — breaking the rule
        assert(!success || after < before);
    }

    // allow this test contract to receive ETH for seedDeposit
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // no special precondition; test any caller
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The rule: if msg.sender is not the owner, withdrawAll must revert.
        // We cannot call owner() directly here because owner is public on C and has a getter.
        // Use that getter to compare.
        address ownerAddr = c.owner();
        assert((msg.sender != ownerAddr) == reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // restrict to callers that are NOT the owner: caller must differ from c.owner()
        // we can observe c.owner() via its public getter
        address owner = c.owner();
        require(msg.sender != owner);
        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // On the original contract, non-owners cannot call withdrawAll (it reverts).
        // The mutant inverted the check so non-owners are allowed; thus for non-owners reverted must be true.
        assert(reverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // restrict to callers that are not the contract owner
        require(caller != c.owner());

        // simulate call from `caller` by using low-level call to this test which then calls c.withdrawAll
        // We need to have this contract perform the call as `caller`. To do that, require caller == msg.sender
        // so the external invoker is the caller we want to test.
        require(caller == msg.sender);

        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        // Rule: if the invoker is not the owner, withdrawAll must revert in the original contract
        assert(reverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // restrict to callers that are not the contract owner
        require(caller != c.owner());

        // ensure the call is made by the provided caller and that this contract has no balance
        // so that withdrawAll would attempt to withdraw from c.balance, not from this test
        require(caller == msg.sender && address(this).balance == 0);

        bool reverted;
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }

        // Rule: if the invoker is not the owner, withdrawAll must revert in the original contract
        assert(reverted == true);
    }
    receive() external payable { }
}

