pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: caller address (actor) and amount to send through sendMoney
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount within contract/init balances but wide
        amount = bound(amount, 0, 1 ether);

        // fund the contract so it can send
        vm.deal(address(this), 2 ether);
        // deposit some ether into c by calling fallback via simple send from this contract
        // we need to send value to c so it has balance to transfer
        c.sendMoney{value: 0}(address(this), 0); // no-op to ensure c exists (not required but harmless)

        // send ETH into c by directly sending to fallback
        (bool s, ) = address(c).call{value: 1 ether}("");
        require(s);

        // Ensure actor is different from address(0) to be a valid EOA in fuzz (avoid vm.prank with zero)
        vm.assume(actor != address(0));

        // Actor will attempt to call sendMoney. If actor == owner (the deployer), in the correct contract
        // onlyOwner allows owner to call; in mutant owner is blocked. We fuzz actor to explore both cases.
        vm.deal(actor, 1 ether);
        vm.prank(actor);

        // Attempt the call and record whether it succeeded (did not revert)
        bool ok;
        try c.sendMoney{value: 0}(actor, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general property we assert (single assertion): if actor is the owner (deployer), the call should succeed on reference
        // We observe this by checking: when actor == address(this) (the deployer was address(this) at setUp), then the call must succeed.
        // On the mutant (where onlyOwner is inverted), calls from the owner will be rejected, so this assertion will fail for those inputs.
        assertTrue(!(actor == address(this)) || ok);
    }
}

