// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to fund the contract and a flag to choose whether recipient will revert
    function testFuzz_property(uint256 fundAmount, bool recipientReverts) public {
        // keep fundAmount in a reasonable wide range (non-negative and not absurdly huge for vm.deal)
        fundAmount = bound(fundAmount, 0, 1 ether);

        // deploy a recipient: either well-behaved or a reverter depending on recipientReverts
        address recipient;
        if (recipientReverts) {
            Reverter r = new Reverter();
            recipient = address(r);
        } else {
            GoodReceiver g = new GoodReceiver();
            recipient = address(g);
        }

        // fund the contract and the owner (test contract is the deployer/owner of c)
        vm.deal(address(this), 2 ether);
        // send funds into c so withdrawAll has a balance to send
        if (fundAmount > 0) {
            (bool sent, ) = address(c).call{value: fundAmount}("");
            require(sent);
        }

        // make c.sendMoney target the recipient so later withdrawAll will send to msg.sender (owner)
        // Here we simulate that owner will withdraw to itself: in both C and mutant, withdrawAll sends to msg.sender (owner)
        // The difference triggers when the owner is a contract whose fallback reverts — so we impersonate a contract owner
        // Deploy an owner-like contract that will call c.withdrawAll; when it receives funds, its fallback may revert.

        OwnerCaller oc = new OwnerCaller(c, recipient);

        // Ensure OwnerCaller has some ETH to pay gas and is recognized as the owner by c
        // c.owner was set to msg.sender at construction time (this test contract). We need the owner to be OwnerCaller.
        // Workaround: we will have this test contract (current owner) call c.sendMoney to set up a value in the recipient,
        // then have OwnerCaller call withdrawAll as owner by first transferring contract ownership is not possible.
        // Instead, to exercise withdrawAll's behavior, we will have the current owner (this) call withdrawAll but set msg.sender
        // for the call to be a contract whose fallback may revert. We use vm.prank to change msg.sender to OwnerCaller.

        // Ensure OwnerCaller has ETH so transfer to it would succeed (if not reverting)
        vm.deal(address(oc), 1 ether);

        // Now call withdrawAll as if OwnerCaller is msg.sender. If recipientReverts == true and mutant uses transfer, the call will revert.
        bool ok;
        vm.prank(address(oc));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C always succeeds (does not revert) for any recipient behavior; thus assertTrue(ok)
        assertTrue(ok);
    }
}

// A minimal helper that reverts on any receive/fallback
contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

// A well-behaved receiver that accepts funds
contract GoodReceiver {
    fallback() external payable {}
    receive() external payable {}
}

// OwnerCaller is a contract used to be the msg.sender when calling c.withdrawAll.
// It does not need to implement any special fallback here; we give it ability to call c.
contract OwnerCaller {
    C c;
    address recipient;
    constructor(C _c, address _recipient) {
        c = _c;
        recipient = _recipient;
    }

    // allow external test to trigger withdrawAll via vm.prank to this contract's address
    function invokeWithdrawAll() public {
        c.withdrawAll();
    }

    fallback() external payable {}
    receive() external payable {}
}

