        // Fund this contract with some ether and deposit into c via fallback to create balance
        // We'll ensure c has at least `amount` balance by depositing `amount` from this contract.
        if (amount > 0) {
            // fund this test contract
            vm.deal(address(this), amount);
            // send amount to c via plain call so fallback increments depositsCount
            (bool sent, ) = address(c).call{value: amount}("");
            require(sent, "funding failed");
        }

        // Record balance before withdraw
        uint256 before = address(c).balance;

        // The reference property (true for correct C) is: after owner calls withdraw(amount),
        // the contract balance equals before - amount (but not below zero). We assert that.
        // We perform the withdraw and then check balance using exactly one assertion reading c.

        // Call withdraw as owner (this contract is the owner)
        // Use try/catch to catch any unexpected revert; we consider revert as failing the property
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call reverted, the reference also would revert (but it doesn't), so we restrict to only cases
        // where the call succeeded and then assert the expected balance relation. Keep admissible inputs wide
        // by assuming the call succeeded (the correct contract will always succeed for owner), so for the
        // reference this is always true; the mutant will sometimes succeed but leave 1 wei behind for amount==1.
        vm.assume(ok);

        uint256 after = address(c).balance;

        // The universal property: after == (before >= amount ? before - amount : 0)
        // This is the single assertion on c's observable balance.
        assertTrue(after == (before >= amount ? before - amount : 0));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // send amount 'amt' from this contract to target; the target may revert when receiving.
    function runTest(address payable target, uint amt) public {
        // Ensure this contract has enough balance to fund the transfer
        require(address(this).balance >= amt);

        // record balance of c before the transfer
        uint balBefore = address(c).balance;

        // deposit funds into C by calling its fallback (which increments depositsCount)
        // to make sure C has at least amt, we send amt to C from this contract
        // Use low-level call to transfer Ether to c so that C's fallback is invoked
        (bool sentToC, ) = address(c).call{value: amt}("");
        require(sentToC);

        // sanity: C must now have increased balance
        require(address(c).balance >= balBefore + amt);

        // Now perform the sendMoney call (this is the changed site in the mutant)
        c.sendMoney(target, amt);

        // After calling sendMoney: on original P, sendMoney uses low-level call ignoring failure so
        // if target reverts the call does not revert and C's balance decreases by amt.
        // On mutant M, the call would revert when target reverts, preventing balance decrease.

        // Observe C's balance after the call
        uint balAfter = address(c).balance;

        // The general rule: C's balance must have decreased by exactly amt (i.e., balAfter == balBefore + amt - amt)
        // which simplifies to balAfter == balBefore
        // We express it as balAfter + amt == balBefore + 0 + amt to keep relation explicit with params
        assert(balAfter + amt == balBefore + 0 + amt);
    }

    // Allow contract to receive Ether for funding tests
    receive() external payable {}
}

